// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(
        uint64 _number,
        uint64 _timestamp,
        uint256 _basefee,
        bytes32 _hash,
        uint64 _sequenceNumber,
        bytes32 _batcherHash,
        uint256 _l1FeeOverhead,
        uint256 _l1FeeScalar
    ) public {
        // Capture the value of the timestamp state variable before the call.
        uint64 before = c.timestamp();

        // Drive c through setL1BlockValues as the designated depositor account.
        vm.prank(c.DEPOSITOR_ACCOUNT());
        try c.setL1BlockValues(_number, _timestamp, _basefee, _hash, _sequenceNumber, _batcherHash, _l1FeeOverhead, _l1FeeScalar) {
            // General rule: the call must never change the timestamp state variable,
            // no matter what _timestamp value is supplied.
            assertTrue(c.timestamp() == before);
        } catch {
            // A revert leaves state untouched, so the rule still holds.
            assertTrue(c.timestamp() == before);
        }
    }
}

