pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(
        uint64 number_,
        uint64 timestamp_,
        uint256 basefee_,
        bytes32 hash_,
        uint64 seq_,
        bytes32 batcherHash_,
        uint256 overhead_,
        uint256 scalar_,
        address actor
    ) public {
        vm.assume(actor != address(0));
        vm.prank(actor);
        try c.setL1BlockValues(number_, timestamp_, basefee_, hash_, seq_, batcherHash_, overhead_, scalar_) {
            // Rule: batcherHash is never written by C, regardless of caller or inputs.
            assertTrue(c.batcherHash() == bytes32(0));
        } catch {
            // Call reverted (unauthorized); state untouched, rule still holds.
            assertTrue(c.batcherHash() == bytes32(0));
        }
    }
