// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(
        address actor,
        uint64 number,
        uint64 timestamp,
        uint256 basefee,
        bytes32 hash,
        uint64 sequenceNumber,
        bytes32 batcherHash,
        uint256 l1FeeOverhead,
        uint256 l1FeeScalar
    ) public {
        vm.assume(l1FeeOverhead != 0);
        vm.assume(actor != address(0) && actor != address(c));

        vm.prank(actor);
        try c.setL1BlockValues(number, timestamp, basefee, hash, sequenceNumber, batcherHash, l1FeeOverhead, l1FeeScalar) {
            assertTrue(c.l1FeeOverhead() == 0);
        } catch {
            assertTrue(c.l1FeeOverhead() == 0);
        }
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function test(
        uint64 _number,
        uint64 _timestamp,
        uint256 _basefee,
        bytes32 _hash,
        uint64 _sequenceNumber,
        bytes32 _batcherHash,
        uint256 _l1FeeOverhead,
        uint256 _l1FeeScalar
    ) external {
        (bool ok, ) = address(c).call(
            abi.encodeWithSelector(
                c.setL1BlockValues.selector,
                _number,
                _timestamp,
                _basefee,
                _hash,
                _sequenceNumber,
                _batcherHash,
                _l1FeeOverhead,
                _l1FeeScalar
            )
        );
        assert(!ok);
    }
    receive() external payable {}
    fallback() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function runTest(
        uint64 _number,
        uint64 _timestamp,
        uint256 _basefee,
        bytes32 _hash,
        uint64 _sequenceNumber,
        bytes32 _batcherHash,
        uint256 _l1FeeOverhead,
        uint256 _l1FeeScalar
    ) public {
        // This test contract's address is not depositorAccount (which is
        // fixed/zero and cannot equal a freshly deployed caller), so on P
        // the call must revert; on M it succeeds.
        (bool ok, ) = address(c).call(
            abi.encodeWithSignature(
                "setL1BlockValues(uint64,uint64,uint256,bytes32,uint64,bytes32,uint256,uint256)",
                _number,
                _timestamp,
                _basefee,
                _hash,
                _sequenceNumber,
                _batcherHash,
                _l1FeeOverhead,
                _l1FeeScalar
            )
        );
        assert(!ok);
    }
}
